-- ADM은 플랫폼 운영 영역이며 Generated MBR 업무 데이터를 직접 CRUD하지 않는다.
DELETE FROM adm_role_button WHERE button_id IN ('MEMBER_READ','MEMBER_CREATE','MEMBER_UPDATE','MEMBER_STATUS','MEMBER_ROLE_GRANT','MEMBER_ROLE_REVOKE');
DELETE FROM adm_role_menu WHERE menu_id = 'MEMBER';
DELETE FROM adm_button WHERE menu_id = 'MEMBER' OR button_id IN ('MEMBER_READ','MEMBER_CREATE','MEMBER_UPDATE','MEMBER_STATUS','MEMBER_ROLE_GRANT','MEMBER_ROLE_REVOKE');
DELETE FROM adm_menu WHERE menu_id = 'MEMBER';
